#!/usr/bin/env node
//
// scripts/sync-prerender-assets.mjs
//
// Runs immediately after `vite build`, as part of `npm run build`.
//
// WHY THIS EXISTS
//
//   public/<route>/index.html is GENERATED by scripts/prerender.mjs and
//   COMMITTED, deliberately: rendering on Netlify would make every deploy
//   depend on a Chromium download. Vite copies public/** into dist/, and a
//   real file beats the SPA fallback, so those pages are what visitors get.
//
//   But a prerendered page carries the <script>/<link> tags of the build it
//   was rendered against — and asset filenames are CONTENT-hashed. The
//   prerender is produced by a LOCAL build; Netlify runs its own build with
//   the site's own environment variables, which are inlined into the bundle.
//   Any difference in those values changes the chunk's bytes, changes its
//   hash, and changes its filename.
//
//   So the committed hashes can never be relied on to match the deploy. On
//   2026-08-27 staging shipped pages asking for index-rca5ZB4w.js while the
//   deploy contained index-BZ2xIuwZ.js. The SPA fallback answered those
//   requests with index.html at status 200 and content-type text/html, the
//   browser refused to execute an HTML module script, React never booted,
//   and every prerendered page — including `/` — rendered as dead markup:
//   visible, styled, and completely unclickable.
//
//   Note which chunks diverged: the entry and supabaseClient, the two that
//   inline configuration. index-*.css and apiClient-*.js hashed identically.
//   A partial match is what makes this so easy to miss.
//
// WHAT IT DOES
//
//   Rewrites every /assets/<name>-<hash>.<ext> reference inside the generated
//   pages in dist/ to the filename THIS build actually produced, matched by
//   logical chunk name. The committed files under public/ are left untouched:
//   they remain the reviewable source of the prerendered CONTENT, and their
//   asset hashes simply stop being load-bearing.
//
//   It fails the build on an unresolvable or ambiguous reference. Silently
//   leaving a broken ref is the failure this script exists to end.
//
import { readFileSync, writeFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { join, dirname, relative } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const DIST = join(ROOT, "dist");
const ASSETS = join(DIST, "assets");

// Same marker prerender.mjs writes, and the same test check-prerender-assets
// uses to tell a generated page from a hand-written static one.
const GENERATED_MARKER = "GENERATED by scripts/prerender.mjs";
const ASSET_REF = /\/assets\/([A-Za-z0-9_.-]+)\.(js|css)/g;

/**
 * "index-rca5ZB4w" -> "index".
 *
 * ⚠️ Do NOT slice at the last "-". Vite's content hash is base64url, so it may
 * itself contain "-" or "_" — "supabaseClient-BzPp-WeK" would reduce to
 * "supabaseClient-BzPp". That misparse is invisible whenever both sides happen
 * to hash without a dash, and appears at random when one of them does. The hash
 * is a fixed-width suffix, so match it as one.
 */
const HASHED_STEM = /^(.*)-[A-Za-z0-9_-]{8}$/;
function logicalName(stem) {
  const m = HASHED_STEM.exec(stem);
  return m ? m[1] : stem;
}

function buildAssetMap() {
  const map = new Map();      // "index|js" -> "index-BZ2xIuwZ.js"
  const ambiguous = new Set();
  for (const file of readdirSync(ASSETS)) {
    const m = /^(.+)\.(js|css)$/.exec(file);
    if (!m) continue;
    const key = `${logicalName(m[1])}|${m[2]}`;
    if (map.has(key)) ambiguous.add(key);
    map.set(key, file);
  }
  return { map, ambiguous };
}

function generatedPages(dir, out = []) {
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) {
      if (name === "assets") continue;
      generatedPages(p, out);
    } else if (name.endsWith(".html")) {
      const html = readFileSync(p, "utf8");
      if (html.includes(GENERATED_MARKER)) out.push({ path: p, html });
    }
  }
  return out;
}

function main() {
  if (!existsSync(DIST) || !existsSync(ASSETS)) {
    console.error("✗ dist/assets not found — run `vite build` first.");
    process.exit(1);
  }

  const { map, ambiguous } = buildAssetMap();
  const pages = generatedPages(DIST);

  if (pages.length === 0) {
    console.error("✗ no generated pages found in dist/ — did prerender output move?");
    process.exit(1);
  }

  const problems = [];
  const pending = [];
  let rewritten = 0;
  let pagesChanged = 0;

  for (const page of pages) {
    const rel = relative(DIST, page.path);
    let changed = 0;

    const next = page.html.replace(ASSET_REF, (whole, stem, ext) => {
      const key = `${logicalName(stem)}|${ext}`;
      if (ambiguous.has(key)) {
        problems.push(`${rel} → ${whole}: several assets share the chunk name "${logicalName(stem)}.${ext}"`);
        return whole;
      }
      const actual = map.get(key);
      if (!actual) {
        problems.push(`${rel} → ${whole}: this build produced no "${logicalName(stem)}.${ext}" chunk`);
        return whole;
      }
      const replacement = `/assets/${actual}`;
      if (replacement !== whole) { changed++; rewritten++; }
      return replacement;
    });

    if (changed > 0) pending.push({ path: page.path, next });
  }

  // Nothing is written until every reference on every page resolves. A build
  // that half-repoints its pages is harder to diagnose than one that stops.
  if (problems.length === 0) {
    for (const { path, next } of pending) writeFileSync(path, next);
    pagesChanged = pending.length;
  }

  if (problems.length) {
    console.error(`✗ prerender asset sync failed — ${problems.length} unresolved reference(s):\n`);
    for (const p of problems) console.error(`   ${p}`);
    console.error("\nA generated page references a chunk this build did not produce.");
    console.error("Re-run `npm run prerender` and commit the result.\n");
    process.exit(1);
  }

  console.log(
    `✓ prerender assets synced: ${pages.length} generated pages, ` +
    `${rewritten} reference(s) repointed across ${pagesChanged} page(s)`
  );
}

main();
